    queue = collections.deque([F])
    while queue:
        u = queue.popleft()
        d = u - 1 if rule == 'add' else u + 1
        if d > 1 and d <= M:
            # x such that d is a divisor or multiple of x
            # Case 1: x is a divisor of d
            for x in range(1, int(d**0.5) + 1):
                if d % x == 0:
                    if dist[x] == float('inf'):
                        dist[x] = dist[u] + 1
                        queue.append(x)
                    if x != 1:
                        other_x = d // x
                        if dist[other_x] == float('inf'):
                            dist[other_x] = dist[u] + 1
                            queue.append(other_x)
            # Case 2: d is a divisor of x
            # x = k*d, and x <= M
            for x in range(d, M + 1, d):
                if dist[x] == float('inf'):
                    dist[x] = dist[u] + 1
                    queue.append(x)
    return dist

